/** 
 * Changes the the local user's nickname in the context of this chat room. If the operation is not supported by the underlying implementation, the method throws an OperationFailedException with the corresponding code.
 * @param nickName the new nickname within the room.
 * @throws OperationFailedException if the setting the new nickname changesfor some reason.
 */
public void setUserNickname(final String nickName) throws OperationFailedException {
  try {
    parentProvider.getIrcStack().setUserNickname(nickName);
  } catch (IllegalArgumentException e) {
    // Handle invalid nickname format
    throw new OperationFailedException("Invalid nickname: " + e.getMessage(), OperationFailedException.ILLEGAL_ARGUMENT);
  } catch (IndexOutOfBoundsException e) {
    // Handle empty nickname
    throw new OperationFailedException("Nickname cannot be empty", OperationFailedException.ILLEGAL_ARGUMENT);
  }
}
